INSERT INTO "agenda_templates" ("key", "kind", "sector", "purpose", "title", "description", "options") VALUES
('ritmo_proximo_ciclo', 'shareholder', NULL, 'general', $t$Ritmo do próximo ciclo$t$, $t$Acelerar os planos ou segurar o passo e consolidar o que já foi feito.$t$, $t$[{"key":"acelerar","label":"Acelerar os planos","gain":"Mais volume e mais mercado já nos próximos trimestres.","loss":"Mais chance de erro de execução e de resultado irregular.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"consolidar","label":"Segurar o passo","gain":"Operação mais organizada e resultados mais regulares.","loss":"A empresa abre mão de parte do avanço possível.","effect":{"effects":[{"metric":"base_growth_pct","direction":-1,"intensity":0.5},{"metric":"quality_multiplier","direction":1,"intensity":0.6}]}}]$t$::jsonb),
('politica_endividamento', 'shareholder', NULL, 'general', $t$Política de endividamento$t$, $t$O caixa permite duas leituras: tomar crédito barato enquanto ele existe, ou usar a sobra para reduzir o que se deve. A assembleia fixa a diretriz.$t$, $t$[{"key":"mais_divida","label":"Usar mais crédito para financiar a expansão","gain":"Obras e compras saem do papel sem esperar o caixa.","loss":"A despesa financeira pesa mais se o cenário piorar.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.7},{"metric":"quality_multiplier","direction":-1,"intensity":0.5}]}},{"key":"menos_divida","label":"Quitar dívida antes do prazo","gain":"Menos juros a pagar e balanço mais leve.","loss":"O dinheiro usado na quitação não vira projeto novo.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.4}]}}]$t$::jsonb),
('prioridade_equipe', 'shareholder', NULL, 'general', $t$Onde a empresa coloca as próximas contratações?$t$, $t$A gestão precisa escolher onde concentrar a equipe nos trimestres seguintes: em frentes novas ou em quem já domina o que a empresa faz hoje.$t$, $t$[{"key":"novos_produtos","label":"Montar um time para produtos novos","gain":"Podem surgir receitas que a empresa ainda não tem.","loss":"Parte dos projetos não vai dar retorno, e a rotina sofre no começo.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.6},{"metric":"quality_multiplier","direction":-1,"intensity":0.3}]}},{"key":"profissionais_experientes","label":"Contratar profissionais experientes para a operação atual","gain":"Processos mais firmes e menos retrabalho.","loss":"A folha sobe sem que haja receita nova imediata.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}}]$t$::jsonb),
('remuneracao_diretoria', 'shareholder', NULL, 'general', $t$Como a diretoria é paga$t$, $t$Um grupo de acionistas escreveu ao conselho pedindo uma posição sobre o bônus da diretoria. O conselho levou duas propostas à votação.$t$, $t$[{"key":"bonus_longo_prazo","label":"Bônus ligado ao resultado de vários anos","gain":"A diretoria passa a olhar para o que dura, não só para o ano.","loss":"O prêmio demora a chegar, e parte dos executivos pode preferir outro emprego.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"bonus_meta_crescimento","label":"Bônus ligado à meta de crescimento do ano","gain":"Equipe empurrada a abrir mercado e fechar negócio rápido.","loss":"Cresce o incentivo a correr riscos para bater a meta.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.6},{"metric":"quality_multiplier","direction":-1,"intensity":0.5}]}}]$t$::jsonb),
('contratos_fornecedores', 'shareholder', NULL, 'general', $t$Contratos com fornecedores$t$, $t$Os contratos de compra vencem neste ciclo. A área de suprimentos levou dois caminhos à assembleia, cada um com seu custo no dia a dia.$t$, $t$[{"key":"renegociar_atuais","label":"Renegociar com os fornecedores atuais","gain":"Preço melhor sem trocar de parceiro e sem interromper entregas.","loss":"A negociação cansa relações antigas e rende menos do que a troca total.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"trocar_mais_barato","label":"Trocar para quem cobra menos","gain":"O custo de compra cai logo e sobra para vender mais barato.","loss":"Entrega atrasada e produto fora do padrão são riscos de quem ainda não se conhece.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.4},{"metric":"quality_multiplier","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('negocio_novo', 'shareholder', NULL, 'general', $t$Entrar num negócio novo?$t$, $t$Surgiu a chance de usar a estrutura da empresa numa área que ela nunca atendeu. Entramos ou ficamos no que sabemos fazer?$t$, $t$[{"key":"entrar","label":"Entrar no negócio novo","gain":"Uma segunda fonte de receita, com mercado ainda por conquistar.","loss":"A empresa pisa em terreno que não conhece, e a atenção se divide.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":1},{"metric":"quality_multiplier","direction":-1,"intensity":0.5}]}},{"key":"focar","label":"Continuar só no que já faz","gain":"Operação afiada e fácil de acompanhar.","loss":"A empresa segue dependendo de um mercado só.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}}]$t$::jsonb),
('varejo_rede_lojas', 'shareholder', 'Varejo', 'general', $t$Rede de lojas$t$, $t$No varejo, ponto de venda vira receita, mas loja ruim vira prejuízo. O que a rede faz com o mapa de lojas?$t$, $t$[{"key":"abrir_lojas","label":"Abrir novas lojas","gain":"A rede chega a mais clientes e a mais cidades.","loss":"Loja nova demora a dar lucro e a conta chega antes.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.9},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"fechar_lojas_ruins","label":"Fechar as lojas que dão prejuízo","gain":"Sai o que perde dinheiro, e a margem melhora.","loss":"A rede encolhe, e alguns clientes ficam sem loja por perto.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.4}]}}]$t$::jsonb),
('varejo_canais_frete', 'shareholder', 'Varejo', 'general', $t$Canais de venda e frete$t$, $t$O cliente compra na loja e pelo celular. A entrega grátis atrai pedidos, mas tem custo.$t$, $t$[{"key":"investir_online","label":"Investir no comércio online","gain":"Alcança quem não vai à loja.","loss":"Frete e entrega comem parte da margem de cada pedido.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.3}]}},{"key":"cortar_frete_gratis","label":"Acabar com o frete grátis e as promoções","gain":"A margem de cada venda melhora na hora.","loss":"Os pedidos diminuem, e parte dos clientes vai comprar de outro.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('energia_infraestrutura', 'shareholder', 'Energia', 'general', $t$Investimento em infraestrutura$t$, $t$Energia depende de obras longas, com retorno diluído por muitos anos. A assembleia decide o cronograma do próximo ciclo.$t$, $t$[{"key":"construir_geracao","label":"Construir nova geração e transmissão","gain":"Mais receita contratada nos anos seguintes.","loss":"Obra grande, retorno lento e risco de atraso e de estouro de custo.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":1},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"adiar_obras","label":"Adiar as obras por um ano","gain":"O caixa fica livre e o risco de obra sai da mesa.","loss":"A capacidade de vender não cresce no período.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.5},{"metric":"base_growth_pct","direction":-1,"intensity":0.7}]}}]$t$::jsonb),
('energia_venda_energia', 'shareholder', 'Energia', 'general', $t$Como vender a energia$t$, $t$A empresa pode travar preço em contratos longos ou vender no mercado livre, onde o preço varia de mês a mês.$t$, $t$[{"key":"contratos_longos","label":"Fechar contratos de longo prazo","gain":"Receita previsível e mais fácil de planejar.","loss":"Fica de fora se o preço de mercado subir.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"mercado_livre","label":"Vender no mercado livre","gain":"Pode capturar preços altos quando a demanda aperta.","loss":"A receita oscila de um mês para o outro.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.5},{"metric":"quality_multiplier","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('mineracao_nova_frente', 'shareholder', 'Mineração', 'general', $t$Nova frente de extração$t$, $t$Mineração exige muito investimento antes da primeira tonelada. A mina nova entra no plano ou a empresa enxuga a operação?$t$, $t$[{"key":"abrir_frente","label":"Abrir uma nova frente de extração","gain":"Mais volume para vender nos próximos anos.","loss":"Investimento alto, retorno só lá na frente e custo de licença incerto.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.9},{"metric":"quality_multiplier","direction":-1,"intensity":0.5}]}},{"key":"vender_mina","label":"Vender uma mina menos produtiva","gain":"Entra caixa, e a operação fica mais simples de gerir.","loss":"Menos minério a vender daqui para frente.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('mineracao_planta', 'shareholder', 'Mineração', 'general', $t$Parada para modernizar a planta$t$, $t$A planta de beneficiamento já trabalha perto do limite. A equipe técnica apresentou dois planos: parar parte da linha para trocar equipamento ou seguir produzindo no ritmo atual.$t$, $t$[{"key":"modernizar_planta","label":"Parar parte da linha e modernizar","gain":"Menos quebra, menos desperdício e mais regularidade no que sai da planta.","loss":"Durante a obra, sai menos minério.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"seguir_produzindo","label":"Seguir produzindo sem parar","gain":"Nenhuma tonelada deixa de ser vendida agora.","loss":"Desgaste e paradas inesperadas aparecem com mais frequência.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.7},{"metric":"quality_multiplier","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('agro_crescer_no_campo', 'shareholder', 'Agronegócio', 'general', $t$Como crescer no campo$t$, $t$No agro dá para crescer de duas formas: plantando em mais terra ou tirando mais de cada hectare. Qual vai ser o caminho?$t$, $t$[{"key":"comprar_terra","label":"Comprar mais terra","gain":"Mais área plantada e mais volume a cada safra.","loss":"Terra nova custa caro, e o chão ainda precisa ser preparado.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"produtividade","label":"Investir em produtividade na área atual","gain":"Mais colheita por hectare e custo mais previsível.","loss":"O volume total cresce devagar, sem área nova.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.2}]}}]$t$::jsonb),
('agro_venda_safra', 'shareholder', 'Agronegócio', 'general', $t$Venda da safra$t$, $t$Um acionista perguntou na última reunião como a empresa pretende vender a próxima colheita, já que o preço do mercado muda toda semana.$t$, $t$[{"key":"vender_antecipado","label":"Vender parte da safra antes da colheita","gain":"Preço conhecido desde já e caixa mais previsível.","loss":"Se o mercado subir depois, a empresa não aproveita.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"guardar_para_depois","label":"Guardar a produção para vender depois","gain":"Chance de vender quando o preço estiver melhor.","loss":"Silo custa dinheiro, e o resultado do ano depende do humor do mercado.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.5},{"metric":"quality_multiplier","direction":-1,"intensity":0.6}]}}]$t$::jsonb),
('banco_carteira_credito', 'shareholder', 'Bancário/Financeiro', 'general', $t$Carteira de crédito$t$, $t$O banco decide o apetite de crédito do ano: liberar mais empréstimo ou apertar a análise de quem pede.$t$, $t$[{"key":"ampliar_credito","label":"Ampliar a oferta de crédito","gain":"Mais clientes e mais juros recebidos.","loss":"Entra gente de risco maior, e a inadimplência tende a subir.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.6}]}},{"key":"reforcar_analise","label":"Reforçar a análise de quem recebe crédito","gain":"Carteira mais saudável e menos calote.","loss":"Menos contratos fechados e menos clientes novos.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.5}]}}]$t$::jsonb),
('banco_agencia_app', 'shareholder', 'Bancário/Financeiro', 'general', $t$Agência ou aplicativo?$t$, $t$O cliente usa cada vez menos a agência. Onde o banco coloca o dinheiro do próximo ciclo?$t$, $t$[{"key":"investir_app","label":"Investir no aplicativo e fechar agências","gain":"Atende mais gente sem depender de endereço.","loss":"O cliente que prefere balcão pode se sentir deixado de lado.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.7},{"metric":"quality_multiplier","direction":-1,"intensity":0.2}]}},{"key":"manter_agencias","label":"Manter a rede de agências","gain":"Relacionamento próximo, que pesa para crédito grande e para quem tem mais idade.","loss":"O custo fixo continua alto e o canal digital cresce menos.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.4},{"metric":"base_growth_pct","direction":-1,"intensity":0.4}]}}]$t$::jsonb),
('tecnologia_pesquisa', 'shareholder', 'Tecnologia', 'general', $t$Pesquisa e desenvolvimento$t$, $t$O orçamento de pesquisa do próximo ciclo está em votação. O volume escolhido define o ritmo de lançamentos dos anos seguintes.$t$, $t$[{"key":"mais_pesquisa","label":"Aumentar o orçamento de pesquisa","gain":"Mais chance de produto novo e de patente própria.","loss":"Custo certo agora, resultado incerto depois.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"segurar_pesquisa","label":"Manter o orçamento de pesquisa enxuto","gain":"Despesa menor e resultado do ano mais previsível.","loss":"A empresa lança menos e pode ficar para trás da concorrência.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.5},{"metric":"base_growth_pct","direction":-1,"intensity":0.7}]}}]$t$::jsonb),
('tecnologia_comprar_construir', 'shareholder', 'Tecnologia', 'general', $t$Comprar ou construir?$t$, $t$Uma startup com produto parecido está à venda. A empresa compra ou desenvolve por conta própria?$t$, $t$[{"key":"comprar_startup","label":"Comprar a startup","gain":"Entra produto pronto e uma equipe que já se conhece.","loss":"O preço é alto, e juntar duas culturas dá trabalho.","effect":{"effects":[{"metric":"base_growth_pct","direction":1,"intensity":0.9},{"metric":"quality_multiplier","direction":-1,"intensity":0.5}]}},{"key":"construir_interno","label":"Construir internamente","gain":"Produto sob medida e equipe própria, sem prêmio de aquisição.","loss":"Leva mais tempo, e o concorrente pode chegar antes.","effect":{"effects":[{"metric":"quality_multiplier","direction":1,"intensity":0.5},{"metric":"base_growth_pct","direction":-1,"intensity":0.2}]}}]$t$::jsonb),
('lucro_reinvestir_distribuir', 'shareholder', NULL, 'profit', $t$O que fazer com o lucro$t$, $t$O balanço fechou com sobra de caixa. Tem quem queira ver o dinheiro voltar para o negócio e tem quem queira receber. Você decide.$t$, $t$[{"key":"reinvestir","label":"Reinvestir mais no negócio","gain":"Mais recursos para crescer nos próximos ciclos.","loss":"Sobra menos dinheiro para o acionista receber agora.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.6},{"metric":"base_growth_pct","direction":1,"intensity":0.6}]}},{"key":"distribuir_mais","label":"Distribuir mais dividendos","gain":"Mais dinheiro na mão de quem é acionista agora.","loss":"Fica menos caixa para investir, e o crescimento perde fôlego.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.4}]}}]$t$::jsonb),
('lucro_calendario_proventos', 'shareholder', NULL, 'profit', $t$Calendário dos proventos$t$, $t$A política de dividendos define quantas vezes por ano a empresa distribui lucro. Três calendários chegam à votação.$t$, $t$[{"key":"trimestral","label":"Pagar a cada trimestre","gain":"Renda mais frequente para quem depende de proventos.","loss":"O caixa sai em fatias menores, e a empresa fica com menos folga para projetos grandes.","effect":{"effects":[{"metric":"dividend_policy","value":"quarterly"},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"semestral","label":"Pagar a cada semestre","gain":"Um meio-termo entre a renda frequente e o caixa para projetos.","loss":"Não agrada nem a quem quer renda constante, nem a quem quer reter mais.","effect":{"effects":[{"metric":"dividend_policy","value":"semiannual"}]}},{"key":"anual","label":"Pagar uma vez por ano","gain":"O caixa fica na empresa por mais tempo para investir.","loss":"O acionista espera o ano inteiro para receber.","effect":{"effects":[{"metric":"dividend_policy","value":"annual"},{"metric":"base_growth_pct","direction":1,"intensity":0.4}]}}]$t$::jsonb),
('lucro_premio_pn', 'shareholder', NULL, 'profit', $t$Quanto a mais as preferenciais recebem$t$, $t$Quando a empresa tem ações preferenciais (PN), elas recebem um dividendo maior que o das ordinárias (ON). Um grupo de acionistas pede que a assembleia revise a diferença.$t$, $t$[{"key":"premio_maior","label":"Aumentar a vantagem da preferencial","gain":"Quem tem PN recebe uma fatia maior de cada distribuição.","loss":"A empresa fica com menos caixa para crescer.","effect":{"effects":[{"metric":"pn_dividend_premium_pct","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}},{"key":"premio_menor","label":"Reduzir a vantagem da preferencial","gain":"Sobra mais caixa na empresa, e o tratamento entre as classes fica mais próximo.","loss":"Quem tem PN recebe menos que antes.","effect":{"effects":[{"metric":"pn_dividend_premium_pct","direction":-1,"intensity":0.6},{"metric":"base_growth_pct","direction":1,"intensity":0.3}]}}]$t$::jsonb),
('lucro_extra_ou_reserva', 'shareholder', NULL, 'profit', $t$Dividendo extra ou reserva de caixa$t$, $t$A empresa pode pagar mais do que o habitual neste balanço ou separar uma reserva para os meses ruins.$t$, $t$[{"key":"dividendo_extra","label":"Pagar um dividendo acima do habitual","gain":"Dinheiro na mão do acionista agora.","loss":"A reserva fica menor, e um ano ruim pesa mais no resultado.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.8},{"metric":"quality_multiplier","direction":-1,"intensity":0.3}]}},{"key":"formar_reserva","label":"Formar uma reserva de caixa","gain":"Um colchão para atravessar anos difíceis sem cortar projeto.","loss":"O dividendo deste balanço fica menor.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.5},{"metric":"quality_multiplier","direction":1,"intensity":0.5}]}}]$t$::jsonb),
('varejo_lucro_lojas_ou_proventos', 'shareholder', 'Varejo', 'profit', $t$Lucro da temporada: lojas ou proventos?$t$, $t$A temporada de vendas terminou com lucro acima do esperado. A diretoria listou duas maneiras de usar o dinheiro.$t$, $t$[{"key":"reformar_lojas","label":"Reformar as lojas com parte do lucro","gain":"Loja nova por dentro vende mais e dá menos problema.","loss":"O dividendo da temporada fica menor.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.5},{"metric":"quality_multiplier","direction":1,"intensity":0.5}]}},{"key":"provento_temporada","label":"Distribuir mais ao fim da temporada","gain":"Quem é acionista é pago pelo bom resultado.","loss":"As reformas ficam para depois, e o crescimento acompanha.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.5},{"metric":"base_growth_pct","direction":-1,"intensity":0.3}]}}]$t$::jsonb),
('energia_lucro_proventos_obras', 'shareholder', 'Energia', 'profit', $t$Proventos e obras no setor de energia$t$, $t$A receita das elétricas é previsível, o que costuma permitir dividendos altos. As obras do ciclo, porém, também precisam de caixa.$t$, $t$[{"key":"payout_alto","label":"Elevar a parcela do lucro distribuída","gain":"Dividendo maior, apoiado numa receita que se repete.","loss":"Menos caixa para as obras do ciclo.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.7},{"metric":"base_growth_pct","direction":-1,"intensity":0.5}]}},{"key":"reter_para_obras","label":"Reter mais lucro para as obras","gain":"As obras andam sem precisar de crédito novo.","loss":"O dividendo diminui.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.7},{"metric":"base_growth_pct","direction":1,"intensity":0.6}]}}]$t$::jsonb),
('mineracao_lucro_ciclo_minerio', 'shareholder', 'Mineração', 'profit', $t$Proventos no ciclo do minério$t$, $t$O preço do minério sobe e desce em ciclos. A política de proventos pode aproveitar a fase boa ou se preparar para a ruim.$t$, $t$[{"key":"pagar_na_alta","label":"Distribuir mais enquanto o preço está alto","gain":"O acionista recebe pelo bom momento, em pagamentos trimestrais.","loss":"A empresa chega à fase fraca com menos reserva.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.6},{"metric":"dividend_policy","value":"quarterly"}]}},{"key":"guardar_para_baixa","label":"Reter caixa para a fase fraca do ciclo","gain":"A empresa atravessa a queda do preço sem cortar operação.","loss":"O dividendo diminui, e passa a sair uma vez por ano.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.6},{"metric":"dividend_policy","value":"annual"}]}}]$t$::jsonb),
('agro_lucro_entressafra', 'shareholder', 'Agronegócio', 'profit', $t$O lucro e a entressafra$t$, $t$Agro recebe pela safra de uma vez e gasta o ano todo. Como a empresa quer distribuir o lucro ao longo desse ciclo?$t$, $t$[{"key":"pagar_pos_colheita","label":"Pagar uma vez por ano, logo depois da colheita","gain":"O dinheiro entra e sai no momento em que o caixa está mais cheio, deixando espaço para investir.","loss":"O acionista espera o ano inteiro para receber.","effect":{"effects":[{"metric":"dividend_policy","value":"annual"},{"metric":"base_growth_pct","direction":1,"intensity":0.4}]}},{"key":"pagar_duas_vezes","label":"Pagar duas vezes por ano","gain":"Uma parte vem na safra e outra na entressafra.","loss":"Em meses de caixa mais curto, a empresa lida com a saída de dinheiro.","effect":{"effects":[{"metric":"dividend_policy","value":"semiannual"},{"metric":"quality_multiplier","direction":-1,"intensity":0.3}]}}]$t$::jsonb),
('banco_lucro_capital', 'shareholder', 'Bancário/Financeiro', 'profit', $t$Capital do banco e dividendos$t$, $t$Um acionista escreveu perguntando por que o banco paga o que paga, já que o lucro cresceu. A diretoria levou o assunto à assembleia.$t$, $t$[{"key":"pagar_mais_banco","label":"Pagar uma parcela maior do lucro","gain":"O acionista recebe mais pelo resultado do ano.","loss":"O banco fica com menos colchão para absorver perdas de crédito.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.6},{"metric":"quality_multiplier","direction":-1,"intensity":0.4}]}},{"key":"reforcar_capital","label":"Reter para reforçar o capital","gain":"Banco mais forte diante de um calote maior que o esperado.","loss":"O dividendo diminui.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.6},{"metric":"quality_multiplier","direction":1,"intensity":0.5}]}}]$t$::jsonb),
('tecnologia_lucro_distribuir', 'shareholder', 'Tecnologia', 'profit', $t$Empresa de tecnologia deve pagar dividendos?$t$, $t$Empresas de tecnologia costumam reter quase tudo para crescer. Esta já tem lucro consistente. O que faz com ele?$t$, $t$[{"key":"comecar_distribuir","label":"Começar a distribuir mais ao acionista","gain":"O acionista passa a receber uma parte maior do lucro que a empresa gera.","loss":"Sobra menos para produto novo, e o ritmo de crescimento cai.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":1,"intensity":0.6},{"metric":"base_growth_pct","direction":-1,"intensity":0.6}]}},{"key":"reinvestir_tudo","label":"Reinvestir quase tudo em produto","gain":"Cada real fica trabalhando em algo que pode render mais lá na frente.","loss":"O dividendo praticamente some neste ciclo.","effect":{"effects":[{"metric":"payout_ratio_pct","direction":-1,"intensity":0.8},{"metric":"base_growth_pct","direction":1,"intensity":0.8}]}}]$t$::jsonb);
